// v1/keystore.mjs — where plugin private keys live (spec 4.3).
//
// One ed25519 seed per installed plugin, generated by the broker at
// install. Default backend: the macOS login Keychain, item
// `com.buwiz.bot.plugin-key`, account = plugin id (keys Rox saved under
// `dev.goldcoders.rox.plugin-key` are read through). The seed goes to
// `security -i` on stdin, never in argv (argv is visible to every process
// through ps). Reads use `find-generic-password -w`, whose output is the
// seed and is never logged. `BUWIZ_KEYSTORE=file:<dir>` keeps one 0600 file
// per plugin instead; every test uses it, or a keychain file of its own,
// and never touches the login Keychain.
import { execFile, spawn } from "node:child_process";
import { chmodSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { isV1 } from "../grammar.mjs";
import { fromB64u } from "./ed.mjs";

export const KEYCHAIN_SERVICE = "com.buwiz.bot.plugin-key";
// Rox's service, before the rename.
export const OLD_KEYCHAIN_SERVICE = "dev.goldcoders.rox.plugin-key";

const checkId = (id) => {
  if (!isV1("pluginId", id)) throw new Error(`not a plugin id: ${String(id).slice(0, 80)}`);
};

const checkSeed = (seed) => {
  if (!fromB64u(seed, 32)) throw new Error("a plugin key seed is 32 bytes of base64url");
};

function fileStore(dir) {
  const path = (id) => join(dir, `${id}.key`);

  return {
    kind: "file",
    async put(id, seed) {
      checkId(id);
      checkSeed(seed);
      mkdirSync(dir, { recursive: true, mode: 0o700 });
      writeFileSync(path(id), seed, { mode: 0o600 });
      chmodSync(path(id), 0o600);
    },
    async get(id) {
      checkId(id);

      return existsSync(path(id)) ? readFileSync(path(id), "utf8").trim() : null;
    },
    async remove(id) {
      checkId(id);
      rmSync(path(id), { force: true });
    },
  };
}

// `security -i` reads commands from stdin; nothing secret reaches argv.
function securityStdin(line) {
  return new Promise((resolve, reject) => {
    const p = spawn("/usr/bin/security", ["-i"], { stdio: ["pipe", "ignore", "pipe"] });
    let err = "";

    p.stderr.on("data", (d) => (err += d));
    p.on("error", reject);
    p.on("close", (code) => (code === 0 && !err.trim() ? resolve() : reject(new Error(`security: ${err.trim().slice(0, 200) || `exit ${code}`}`))));
    // the session ends at the end of stdin (`security -i` has no quit command)
    p.stdin.end(`${line}\n`);
  });
}

const security = (args) =>
  new Promise((resolve) => execFile("/usr/bin/security", args, { timeout: 10000 }, (e, out) => resolve(e ? null : String(out))));

// Items under `service`, read through to `old`: a key found only there is
// copied to `service` and the old item stays (a downgraded broker still
// finds it); a remove deletes both. `keychain` is a keychain file (no
// spaces), or the user's search list when unset; tests give their own.
export function keychainStore({ service = KEYCHAIN_SERVICE, old = OLD_KEYCHAIN_SERVICE, keychain } = {}) {
  const kc = keychain ? [keychain] : [];
  const put = (id, seed, at = service) =>
    // ids and seeds hold no spaces or quotes (grammar, base64url), so the
    // line needs no quoting
    securityStdin(`add-generic-password -U -s ${at} -a ${id} -w ${seed}${keychain ? ` ${keychain}` : ""}`);
  const find = async (at, id) => {
    const out = await security(["find-generic-password", "-s", at, "-a", id, "-w", ...kc]);

    return out ? out.trim() : null;
  };

  return {
    kind: "keychain",
    async put(id, seed) {
      checkId(id);
      checkSeed(seed);
      await put(id, seed);
    },
    async get(id) {
      checkId(id);
      const seed = await find(service, id);

      if (seed) return seed;
      const was = await find(old, id);

      // the key is read either way; a failed copy is tried again next read
      if (was && fromB64u(was, 32)) await put(id, was).catch(() => console.error(`  keystore ${id}: copying the key to ${service} failed`));

      return was;
    },
    async remove(id) {
      checkId(id);
      for (const at of [service, old]) await security(["delete-generic-password", "-s", at, "-a", id, ...kc]);
    },
  };
}

/** The keystore BUWIZ_KEYSTORE names (`file:<dir>`), else the Keychain. */
export function keystore(spec = process.env.BUWIZ_KEYSTORE || "") {
  if (spec.startsWith("file:")) return fileStore(spec.slice(5));

  if (spec && spec !== "keychain") throw new Error(`BUWIZ_KEYSTORE must be file:<dir> or keychain, not ${spec.slice(0, 40)}`);

  return keychainStore();
}
